def _virtual(osdata):
    '''
    Returns what type of virtual hardware is under the hood, kvm or physical
    '''
    # This is going to be a monster, if you are running a vm you can test this
    # grain with please submit patches!
    # Provides:
    #   virtual
    grains = {'virtual': 'physical'}
    try:
        if not subprocess.check_call('lspci',
                stdout=subprocess.PIPE,stderr=subprocess.PIPE):
            isLspciPresent=True
        else:
            isLspciPresent=False
    except:
        isLspciPresent=False
    if isLspciPresent:
        model=subprocess.Popen( 
                'lspci | grep -i system',
                shell=True,
                stdout=subprocess.PIPE
                ).communicate()[0]
        if model.lower().count('vmware'):
            grains['virtual'] = 'VMware'
        elif model.lower().count('virtualbox'):
            grains['virtual'] = 'VirtualBox'
        elif model.lower().count('qemu'):
            grains['virtual'] = 'kvm'
    choices =  ['Linux', 'OpenBSD', 'SunOS', 'HP-UX']
    isdir = os.path.isdir
    if osdata['kernel'] in choices:
        if isdir('/proc/vz'):
            if os.path.isfile('/proc/vz/version'):
                grains['virtual'] = 'openvzhn'
            else:
                grains['virtual'] = 'openvzve'
        elif isdir('/proc/sys/xen') or isdir('/sys/bus/xen') or isdir('/proc/xen'):
            grains['virtual'] = 'xen'
            if os.path.isfile('/proc/xen/xsd_kva'):
                grains['virtual_subtype'] = 'Xen Dom0'
            else:
                if os.path.isfile('/proc/xen/capabilities'):
                    grains['virtual_subtype'] = 'Xen full virt DomU'
                else:
                    grains['virtual_subtype'] = 'Xen paravirt DomU'
        elif isdir('/.SUNWnative'):
            grains['virtual'] = 'zone'
        elif os.path.isfile('/proc/cpuinfo'):
            if 'QEMU Virtual CPU' in open('/proc/cpuinfo', 'r').read():
                grains['virtual'] = 'kvm'
    elif osdata['kernel'] == 'FreeBSD':
        model = subprocess.Popen(
                '/sbin/sysctl hw.model',
                shell=True,
                stdout=subprocess.PIPE
                ).communicate()[0].split(':')[1].strip()
        if 'QEMU Virtual CPU' in model:
            grains['virtual'] = 'kvm'
    return grains

