                            else:
                                ret['comment'].append(this_ret['comment'])
                else:
                    ret['result'] = False
                    ret['comment'].append('Unable to obtain ADSI object')
            except pywintypes.com_error as com_err:
                ret['result'] = False
                friendly_error = ''
                if len(com_err.excepinfo) >= 2:
