                        friendly_error = com_err.excepinfo[2].rstrip('\r\n')
                ret['comment'].append((
                        'Failed to create user {0}.  {1}'
                        ).format(name, friendly_error))
        else:
            ret['result'] = False
            ret['comment'].append((
                    'A password was not supplied for new user {0}.'
                    ).format(name))
    else:
        ret['result'] = None
        ret['comment'].append((
                'The user {0} already exists.'
                ).format(name))

