                else:
                    desired_ports.append(port_def)
            desired_ports.sort()
            log.trace('dockerng.running ({0}): munged actual value: {1}'
                        .format(item, actual_ports))
            log.trace('dockerng.running ({0}): munged desired value: {1}'
                        .format(item, desired_ports))
