                DagRun.run_type == DagRunType.MANUAL,
                DagRun.conf.isnot(None),
            )
            .group_by(DagRun.conf)
            .order_by(func.max(DagRun.logical_date).desc())
            .limit(num_recent_confs)
        )
        recent_confs = {
