                            record["state"] = state
                            break
                    if None in record["mapped_states"]:
                        # When turning the dict into JSON we can't have None as a key,
                        # so use the string that the UI does.
                        record["mapped_states"]["no_status"] = record["mapped_states"].pop(None)

